let __manualContentCache=null;
function manualNorm(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
function manualDistance(a,b,max=2){if(a===b)return 0;if(Math.abs(a.length-b.length)>max)return max+1;let p=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let c=[i],mn=i;for(let j=1;j<=b.length;j++){const v=Math.min(c[j-1]+1,p[j]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));c[j]=v;mn=Math.min(mn,v)}if(mn>max)return max+1;p=c}return p[b.length]}
function manualTokens(q){return manualNorm(q).split(' ').filter(Boolean)}
function manualFuzzyHit(hay,t){if(!t)return false;if(hay.includes(t))return true;if(t.length<4)return false;const md=t.length>=9?3:2;return hay.split(' ').some(w=>w.length>=3&&manualDistance(t,w,md)<=md)}
function ensureManualContentIndex(){if(__manualContentCache)return __manualContentCache;const idx=window.__PROGRAMME_PAGE_INDEX;if(!Array.isArray(idx))return null;const m={};for(const p of idx){const f=p.f;if(!f)continue;(m[f]||(m[f]=[])).push(manualNorm(p.t))}__manualContentCache=m;return m}
function manualSearchScore(m,q){const nq=manualNorm(q);if(!nq)return 1;const toks=manualTokens(nq);const aliases=(MANUAL_SEARCH_ALIASES[m.id]||[]).map(manualNorm);const meta=manualNorm([m.title,m.subtitle,m.category,m.source,m.status,m.note,...aliases].join(' '));let score=0;if(meta.includes(nq))score+=150;for(const t of toks){if(manualFuzzyHit(meta,t))score+=35}const pageMap=ensureManualContentIndex();if(pageMap&&pageMap[m.file]){let best=0;for(const h of pageMap[m.file]){let hit=0;if(h.includes(nq))hit+=90;for(const t of toks)if(manualFuzzyHit(h,t))hit+=18;best=Math.max(best,hit)}score+=best}return score}

