function pageNorm(p){return p._n||(p._n=norm(p.t))}
function countHits(hay,needle){if(!needle)return 0;let n=0,i=0;while((i=hay.indexOf(needle,i))>=0&&n<8){n++;i+=needle.length}return n}
function pageScore(p,qObj){const h=pageNorm(p);let sc=0;if(qObj.phrase&&h.includes(qObj.phrase))sc+=130+Math.min(30,countHits(h,qObj.phrase)*5);let exact=0;for(const t of qObj.tokens){if(h.includes(t)){exact++;sc+=28+Math.min(15,countHits(h,t)*3)}}if(qObj.tokens.length&&exact===qObj.tokens.length)sc+=55;if(norm(p.m).includes(qObj.phrase))sc+=25;return sc}
function excerptFor(p,qObj){const raw=String(p.t||'').replace(/\s+/g,' ').trim();const low=raw.toLowerCase();const candidates=[qObj.phrase,...qObj.tokens].filter(Boolean);let idx=-1;for(const c of candidates){idx=low.indexOf(c.toLowerCase());if(idx>=0)break}if(idx<0)idx=0;const start=Math.max(0,idx-180),end=Math.min(raw.length,idx+620);let out=raw.slice(start,end);if(start>0)out='…'+out;if(end<raw.length)out+='…';return out}

function topicLabel(qObj){const s=(qObj.phrase||qObj.original||'this topic').replace(/\b\w/g,c=>c.toUpperCase());return s;}

function sourceSegments(p,qObj){
  const raw=String(p.t||'')
    .replace(/\r/g,' ')
    .replace(/\s+/g,' ')
    .replace(/^\s*\d+\s+/,'')
    .trim();
  const prepared=raw
    .replace(/\s+(?=\d+\.\d+(?:\.\d+)?\s+[A-Z])/g,' ||| ')
    .replace(/\s+(?=(?:i|ii|iii|iv|v|vi|vii|viii|ix|x)\)\s+)/gi,' ||| ');
  let segs=prepared.split(/\s*\|\|\|\s*|(?<=[.!?])\s+/).map(s=>s.trim()).filter(Boolean);
  const seen=new Set(), ranked=[];
  for(const s of segs){
    if(s.length<28||s.length>650)continue;
    if(/^(table of contents|index|chapter \d+\s*)$/i.test(s))continue;
    const h=norm(s);
    let sc=0, hits=0;
    if(qObj.phrase&&h.includes(qObj.phrase)){sc+=120;hits+=2}
    for(const t of qObj.tokens){if(t.length>1&&h.includes(t)){sc+=28;hits++}}
    if(!hits)continue;
    if(/\b(must|shall|may|should|required|entitled|eligible|granted|apply|application|period|rate|definition|treatment|recommended|test|follow|dose|days|weeks|months)\b/i.test(s))sc+=12;
    const key=h.slice(0,180);
    if(seen.has(key))continue;
    seen.add(key);
    ranked.push([sc,s]);
  }
  return ranked.sort((a,b)=>b[0]-a[0]).map(x=>x[1]);
}

function uniqueTopPages(matches,max=4){
  const out=[],seen=new Set();
  for(const x of matches){
    const p=x[1],key=p.f+'|'+p.p;
    if(seen.has(key))continue;
    seen.add(key);out.push(p);
    if(out.length>=max)break;
  }
  return out;
}

function naturalSourceAnswer(matches,qObj){
  if(!matches.length)return'';
  const pages=uniqueTopPages(matches,4);
  const staffPages=pages.filter(p=>p.g==='staff');
  const focus=(staffPages.length?staffPages:pages);
  const points=[],seen=new Set();
  for(const p of focus){
    for(const s of sourceSegments(p,qObj)){
      const k=norm(s).slice(0,180);
      if(seen.has(k))continue;
      seen.add(k);points.push(s);
      if(points.length>=6)break;
    }
    if(points.length>=6)break;
  }
