    exact.push([sc,p]);
  }
  exact.sort((a,b)=>b[0]-a[0]);
  if(exact.length)return exact.slice(0,limit);

  // If the exact corrected phrase is absent, require EVERY corrected token.
  // This keeps typo tolerance without returning merely related topics.
  const allTokens=[];
  for(const p of PROGRAMME_PAGE_INDEX){
    const h=pageNorm(p);
