giaScore(item,q){
  const qq=giaCleanQuery(q),qt=qq.split(" ").filter(Boolean),title=norm(item.title),hay=item.hay;
  let sc=0;
  if(title===qq)sc+=500;
  if(title.includes(qq))sc+=260;
  if(hay.includes(qq))sc+=150;
  qt.forEach(t=>{
    if(title.split(" ").includes(t))sc+=90;
    else if(title.includes(t))sc+=65;
    if(hay.includes(t))sc+=35;
    if(t.length>=4){
      const words=hay.split(" ").filter(w=>Math.abs(w.length-t.length)<=2).slice(0,100);
      let best=9;for(const w of words){const d=giaLev(t,w);if(d<best)best=d;if(best===1)break}
      if(best===1)sc+=24;else if(best===2&&t.length>=6)sc+=10;
    }
  });
  if(item.section==="manuals"&&/\bmanual|guideline|staff|leave\b/.test(qq))sc+=45;
  if(item.section==="training"&&/\blearn|course|training|certificate\b/.test(qq))sc+=45;
  if(item.section==="services"&&/\bclinic|centre|hospital|service|location|where\b/.test(qq))sc+=45;
  if(item.section==="research"&&/\bresearch|data|stat|census|mortality|article\b/.test(qq))sc+=45;
  if(item.section==="gallery"&&/\bgallery|picture|photo|image|media\b/.test(qq))sc+=45;
  if(item.action==="snake"&&/\bsnake|game|arcade|play\b/.test(qq))sc+=400;
  return sc;
}
function giaNavigate(i){
  const item=GIA_SITE_INDEX?.[Number(i)];if(!item)return;
  closeGuide();
  if(item.action==="snake"){setTimeout(()=>document.getElementById("hstuArcadePlay")?.click(),120);return}
  const nav=document.querySelector(`[data-view="${item.section}"]`);
  if(nav)nav.click();
  setTimeout(()=>{
    if(item.el&&document.body.contains(item.el)){item.el.scrollIntoView({behavior:"smooth",block:"center"});item.el.classList.add("gia-found-flash");setTimeout(()=>item.el.classList.remove("gia-found-flash"),1800)}
    else document.getElementById("view-"+item.section)?.scrollIntoView({behavior:"smooth",block:"start"});
    const q=giaCleanQuery(input.value);
    // Reuse destination search boxes where they exist.
    const root=document.getElementById("view-"+item.section);
    const box=root?.querySelector('input[type="search"],input[placeholder*="Search"]');
    if(box&&q&&!["manuals","learning","research","gallery","find services"].includes(q)){box.value=q;box.dispatchEvent(new Event("input",{bubbles:true}));box.dispatchEvent(new Event("change",{bubbles:true}))}
    // Gallery category jump.
    if(item.section==="gallery"){const cat=item.title.match(/^(HIV|STI|TB|PrEP)/i)?.[1];if(cat){[...document.querySelectorAll("[data-gallery-filter]")].find(b=>b.dataset.galleryFilter.toLowerCase()===cat.toLowerCase())?.click()}}
  },160);
}
window.giaNavigate=giaNavigate;
function runSearch(){
  const q=input.value.trim();
  if(!q){results.innerHTML='<div class="guide-noresult"><h3>What are you looking for?</h3><p>Search manuals, learning, research, services, gallery resources and more. You don’t need the exact spelling.</p></div>';return}
  if(!GIA_SITE_INDEX)giaBuildIndex();
  const cleaned=giaCleanQuery(q);
  const ranked=GIA_SITE_INDEX.map((x,i)=>({x,i,score:giaScore(x,q)})).filter(r=>r.score>=35).sort((a,b)=>b.score-a.score).slice(0,8);
  const corrected=cleaned!==norm(q)?`<div class="query-correction">I’m reading <b>${esc2(q)}</b> as <b>${esc2(cleaned)}</b>.</div>`:"";
  if(!ranked.length){results.innerHTML=corrected+`<div class="guide-noresult"><h3>I couldn’t find “${esc2(q)}” in the Resource Centre yet.</h3><p>Try a shorter term or another spelling. I’ll only show destinations that are actually available here.</p></div>`;return}
  results.innerHTML=corrected+`<div class="gia-finder-intro"><b>I found ${ranked.length===1?"a match":"a few good matches"}.</b><span>Choose one and I’ll take you there.</span></div>`+
  ranked.map(r=>{const m=GIA_SECTION_META[r.x.section]||{};return `<article class="gia-find-card"><div><span class="gia-find-badge">${esc2(m.label||r.x.section)}</span><h3>${esc2(r.x.title)}</h3><p>${esc2(r.x.desc||m.desc||"Open this Resource Centre destination.")}</p></div><button type="button" onclick="giaNavigate(${r.i})">${r.x.action==="snake"?"Play Snake →":"Go there →"}</button></article>`}).join("");
}
searchBtn.addEventListener('click',runSearch);
input.addEventListener('keydown',e=>{if(e.key==='Enter')runSearch()});
document.getElementById('clinicalShortcuts').addEventListener('click',e=>{const b=e.target.closest('[data-guide-q]');if(!b)return;input.value=b.dataset.guideQ;runSearch()});
})();
</script>
