Each(t=>{
    if(title.split(" ").includes(t))sc+=90;
    else if(title.includes(t))sc+=65;
    if(hay.includes(t))sc+=35;
    if(t.length>=4){
      const words=hay.split(" ").filter(w=>Math.abs(w.length-t.length)<=2).slice(0,100);
      let best=9;for(const w of words){const d=giaLev(t,w);if(d<best)best=d;if(best===1)break}
      if(best===1)sc+=24;else if(best===2&&t.length>=6)sc+=10;
    }
  });
  if(item.section==="manuals"&&/\bmanual|guideline|staff|leave\b/.test(qq))sc+=45;
  if(item.section==="training"&&/\blearn|course|training|certificate\b/.test(qq))sc+=45;
  if(item.section==="services"&&/\bclinic|centre|hospital|service|location|where\b/.test(qq))sc+=45;
  if(item.section==="research"&&/\bresearch|data|stat|census|mortality|article\b/.test(qq))sc+=45;
  if(item.section==="gallery"&&/\bgallery|picture|photo|image|media\b/.test(qq))sc+=45;
  if(item.action==="snake"&&/\bsnake|game|arcade|play\b/.test(qq))sc+=400;
  return sc;
